<?php

declare(strict_types=1);

namespace App\Catalog\Application\Command\CreateProduct;

use App\Shared\Application\Bus\Command;
use App\Shared\Domain\Identity\ProductId;
use App\Shared\Domain\Measurement\MeasurementCategory;

/**
 * Adds a product to the catalog.
 *
 * Carries typed values, not raw request data: turning JSON into a ProductId
 * and a MeasurementCategory, and answering 400 when that fails, is the HTTP
 * layer's job (D-07). By the time a command exists, its values are
 * well-formed; whether they satisfy the business rules is the domain's call.
 * The id is generated by the caller before dispatch (see CommandBus).
 */
final readonly class CreateProduct implements Command
{
    public function __construct(
        public ProductId $id,
        public string $name,
        public MeasurementCategory $category,
    ) {
    }
}
